import time, statistics
import mlx.core as mx

src = '''
uint lane = thread_index_in_simdgroup;
uint sg = simdgroup_index_in_threadgroup;
uint r = threadgroup_position_in_grid.x * (32 / S) * SG + sg * (32 / S) + lane / S;
uint kl = lane % S;
