    n,k=w.shape
    return kern(inputs=[w,x],template=[('N',n),('K',k),('S',s),('SG',sg),('U',u)],grid=(((n+(32//s)*sg-1)//((32//s)*sg))*sg*32,1,1),threadgroup=(sg*32,1,1),output_shapes=[(1,n)],output_dtypes=[mx.bfloat16])[0]
def timing(f,n=50):
    mx.eval(f())
    ts=[]
    for _ in range(5):
        st=time.perf_counter()
        for i in range(n): mx.eval(f())
        ts.append((time.perf_counter()-st)*1000/n)
    return statistics.median(ts)
for n,k in [(4096,1024),(6144,1024),(1024,2048),(1024,3072),(151936,1024)]:
    w=mx.random.normal((n,k)).astype(mx.bfloat16)
    x=mx.random.normal((1,k)).astype(mx.bfloat16)
    mx.eval(w,x)
    ref=x@w.T; mx.eval(ref)
    base=timing(lambda:x@w.T,n=20)
    print('shape',n,k,'stock',base,flush=True)
    vals=[]
    for s in [8,16,32]:
        for sg in [2,4,8]:
            for u in [1,2,4,8]:
                if k//4 % (s*u): continue
                f=lambda:custom(w,x,s,sg,u)
                y=f(); mx.eval(y)
                dt=timing(f,n=20)
                err=mx.max(mx.abs(y.astype(mx.float32)-ref.astype(mx.float32))).item()
                vals.append((dt,s,sg,u,err))
    print('best', sorted(vals)[:8], 'ratio',base/min(v[0] for v in vals),flush=True)
