from mlx_lm.models.cache import KVCache

class Engine(Base):
    def __init__(self,model):
        super().__init__(model)
        self.prefill_graphs={}

    def _graph(self,offset,logits):
        def f(tokens,keys,values):
            cc=[]
            for k,v in zip(keys,values):
                c=KVCache();c.keys=k;c.values=v;c.offset=offset
                cc.append(c)
            h=self._hidden(tokens,cc,last_only=logits)
            states=([c.keys for c in cc],[c.values for c in cc])
            if logits:
                h=self.model.model.norm(h[:,-1:,:])
                return gemv(self.model.model.embed_tokens.weight,h,sg=8,u=8)[0,0],*states
            return states
        return mx.compile(f)

    def _prefill(self,tokens,cache,logits):
        off=cache[0].offset
        n=tokens.shape[1]
        with mx.stream(self.stream):
            for c in cache:
                if c.keys is None:
                    cap=((n+c.step-1)//c.step)*c.step
                    c.keys=mx.zeros((1,self.args.num_key_value_heads,cap,self.args.head_dim),mx.bfloat16)
                    c.values=mx.zeros_like(c.keys)
                elif off+n>c.keys.shape[2]:
                    extra=((off+n-c.keys.shape[2]+c.step-1)//c.step)*c.step
                    z=mx.zeros((1,self.args.num_key_value_heads,extra,self.args.head_dim),mx.bfloat16)
                    c.keys=mx.concatenate([c.keys,z],axis=2)
                    c.values=mx.concatenate([c.values,z],axis=2)
            key=(off,logits)
            if key not in self.prefill_graphs:self.prefill_graphs[key]=self._graph(off,logits)
            out=self.prefill_graphs[key](tokens,[c.keys for c in cache],[c.values for c in cache])
            if logits:lg,ks,vs=out
            else:ks,vs=out
            for c,k,v in zip(cache,ks,vs):
                c.keys=k;c.values=v;c.offset+=n
            return lg if logits else None

    def forward(self,tokens,cache):
        if tokens.shape[1]>1:return self._prefill(tokens,cache,True)
        return super().forward(tokens,cache)
